// Turn the Stripe charge into the fields the receipt template needs.
// Stripe sends money in minor units (cents); zero-decimal currencies (JPY,
// KRW…) are the exception and are handled by Intl, not by hand.

const event = $input.first().json;
const charge = event.data && event.data.object ? event.data.object : event;
const defaults = $('Set company details').first().json;

const escape = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const currency = String(charge.currency || 'usd').toUpperCase();
const zeroDecimal = ['BIF','CLP','DJF','GNF','JPY','KMF','KRW','MGA','PYG','RWF','UGX','VND','VUV','XAF','XOF','XPF'];
const divisor = zeroDecimal.includes(currency) ? 1 : 100;
const money = (minor) => new Intl.NumberFormat(defaults.locale || 'en-US', {
  style: 'currency', currency,
}).format(Number(minor || 0) / divisor);

const billing = charge.billing_details || {};
const card = charge.payment_method_details && charge.payment_method_details.card
  ? charge.payment_method_details.card : null;

const paidAt = new Date(Number(charge.created || Date.now() / 1000) * 1000);

// One line per receipt: a charge has a description, not line items. If you
// pass items in charge.metadata.items as "desc|qty|unit;desc|qty|unit", they
// become rows instead.
let rowsHtml = '';
const items = String((charge.metadata && charge.metadata.items) || '').trim();
if (items) {
  rowsHtml = items.split(';').map((line) => {
    const [desc, qty, unit] = line.split('|').map((s) => s.trim());
    const amount = Number(qty || 1) * Number(unit || 0);
    return `<tr><td>${escape(desc)}</td><td class="num">${escape(qty || 1)}</td>` +
      `<td class="num">${money(unit)}</td><td class="num">${money(amount)}</td></tr>`;
  }).join('');
} else {
  rowsHtml = `<tr><td>${escape(charge.description || 'Payment')}</td><td class="num">1</td>` +
    `<td class="num">${money(charge.amount)}</td><td class="num">${money(charge.amount)}</td></tr>`;
}

const fields = {
  receipt_number: String(charge.id || '').replace(/^ch_/, 'R-').slice(0, 20),
  paid_on: paidAt.toLocaleDateString(defaults.locale || 'en-US', { year: 'numeric', month: 'long', day: 'numeric' }),
  customer_name: billing.name || charge.customer_name || 'Customer',
  customer_email: charge.receipt_email || billing.email || '',
  description: charge.description || 'Payment',
  rows_html: rowsHtml,
  total: money(charge.amount),
  currency,
  card_label: card ? `${String(card.brand || 'card').toUpperCase()} •••• ${card.last4}` : 'Card',
  charge_id: charge.id || '',
};

// ---------------------------------------------------------------------------
// The PDF request is assembled here, not in the HTTP node.
//
// Why: a JSON body written by hand with "={{ ... }}" inside the quotes is not
// an expression to n8n — only a field whose whole value starts with "=" is.
// Written that way, the literal text {{ $json.rows_html }} was sent to the API
// and printed on the page. Building the object here and sending it as one
// JSON.stringify keeps every quote in rows_html intact.
const PDF_TEMPLATE = "<!doctype html><html><head><meta charset=\"utf-8\"><style>@page{size:A4;margin:18mm 16mm 20mm}body{font-family:'Open Sans',sans-serif;color:#1f1c19;font-size:12.5px;line-height:1.5;margin:0}header{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:2px solid #1f1c19;padding-bottom:12px;margin-bottom:20px}.brand{font-size:19px;font-weight:bold}.brand small{display:block;font-size:11px;font-weight:normal;color:#5c534b}.meta{text-align:right;font-size:11.5px;color:#5c534b}.meta b{display:block;font-size:14px;color:#1f1c19}.paid{display:inline-block;border:1.5px solid #1f1c19;border-radius:3px;padding:1px 7px;font-size:9px;letter-spacing:.14em;text-transform:uppercase;margin-top:4px}.label{font-size:8.5px;letter-spacing:.14em;text-transform:uppercase;color:#6b625b;margin-bottom:4px}.two{display:flex;gap:32px;margin-bottom:18px}.two>div{flex:1}table{width:100%;border-collapse:collapse}thead{display:table-header-group}tr{break-inside:avoid}th{text-align:left;font-size:8.5px;letter-spacing:.12em;text-transform:uppercase;color:#6b625b;border-bottom:1px solid #d8d2ca;padding:0 0 6px;font-weight:normal}td{padding:8px 0;border-bottom:1px solid #f2eee9;vertical-align:top}.num{text-align:right;white-space:nowrap}.totals{margin:18px 0 0 auto;width:54%;break-inside:avoid}.totals td{border:0;padding:5px 0}.totals .grand td{border-top:2px solid #1f1c19;padding-top:9px;font-size:15px;font-weight:bold}footer{margin-top:28px;font-size:10.5px;color:#6b625b;border-top:1px solid #d8d2ca;padding-top:10px}</style></head><body><header><div class=\"brand\">{{company.name}}<small>{{company.address}}</small></div><div class=\"meta\"><b>Receipt {{receipt_number}}</b><div>{{paid_on}}</div><span class=\"paid\">Paid</span></div></header><div class=\"two\"><div><div class=\"label\">Received from</div><p><b>{{customer_name}}</b><br>{{customer_email}}</p></div><div><div class=\"label\">Payment method</div><p>{{card_label}}<br>Charge {{charge_id}}</p></div></div><table><thead><tr><th>Description</th><th class=\"num\">Qty</th><th class=\"num\">Unit</th><th class=\"num\">Amount</th></tr></thead><tbody>{{{rows_html}}}</tbody></table><table class=\"totals\"><tr class=\"grand\"><td>Total paid ({{currency}})</td><td class=\"num\">{{total}}</td></tr></table><footer>Thank you for your payment. Questions about this receipt: {{company.support_email}}</footer></body></html>";

return [{
  json: {
    ...fields,
    pdf_template: PDF_TEMPLATE,
    pdf_data: {
      company: {
        name: defaults.company_name,
        address: defaults.company_address,
        support_email: defaults.support_email,
      },
      ...fields,
    },
  },
}];

